    "path": "runLocal/templates/.runlocal.yaml.example",
    "content": "# .runlocal.yaml — optional per-repo override. Copy to the repo root as\n# `.runlocal.yaml` to bypass auto-detection. Every key is optional; anything you\n# omit falls back to detection. Flat keys + one nested `env:` block only.\n\n# Friendly name (used for docker image tags, logging).\nservice_name: my-service\n\n# Force the stack instead of auto-detecting from marker files.\n# One of: node | python | go | maven | gradle | rust | ruby | php\n#         compose | docker | make | procfile\n# stack: node\n\n# Override the dependency-install step (runs in the repo root).\n# install_cmd: npm ci\n\n# Optional build step you can reference from run_cmd if needed.\n# build_cmd: npm run build\n\n# The command that starts the service. If set, detection is skipped entirely.\nrun_cmd: npm run dev\n\n# Exposed as $PORT to the service (and used in default run commands).\nport: 3000\n\n# Load environment variables from this file (relative to repo root).\n# env_file: .env.local\n\n# Inline environment variables (override values from env_file).\nenv:\n  NODE_ENV: development\n  LOG_LEVEL: debug\n",
